Let's design parser:
```
private static int getRequiredWebpApiLevel(byte[] data) {
    if (data == null || data.length < 12) return -1;
    if (!fourCc(data, 0, 'R','I','F','F') || !fourCc(data, 8, 'W','E','B','P')) return -1;

    int offset = 12;
    boolean lossless = false;
    boolean alpha = false;
    boolean hasVp8 = false;

    while (offset + 8 <= data.length) {
        int id = readInt(data, offset);
        int size = readInt(data, offset + 4);
        if (size < 0) break;
        int next = offset + 8 + size;
        if ((size & 1) != 0) next++;
        if (next < 0 || next > data.length) break;
        int dataOffset = offset + 8;

        if (id == fourCc("VP8X") && size >= 10) {
            int flags = data[dataOffset] & 0xFF;
            if ((flags & 0x10) != 0) alpha = true;
        } else if (id == fourCc("VP8L")) {
            lossless = true;
        } else if (id == fourCc("ALPH")) {
            alpha = true;
        } else if (id == fourCc("VP8 ")) {
            hasVp8 = true;
        }

        offset = next;
    }

    if (lossless || alpha) return 18;
    if (hasVp8) return 15;
    return -1;
}
```
